    fails += check(&.{ 0x48, 0xF7, 0xE1 }, .@"mul", .{ gp.r64(.rdx), gp.r64(.rax), gp.r64(.rcx) }, .{  }, "48F7E1 mul(rdx, rax, rcx)");
