    fails += check(&.{ 0x48, 0xF7, 0xA4, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"mul", .{ gp.r64(.rdx), gp.r64(.rax), gp.qword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "48F7A41180000000 mul(rdx, rax, qword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0xF6, 0xD9 }, .@"neg", .{ gp.r8(.rcx) }, .{  }, "F6D9 neg(cl)");
    fails += check(&.{ 0xF6, 0xDD }, .@"neg", .{ gp.r8hi(.rcx) }, .{  }, "F6DD neg(ch)");
    try std.testing.expectEqual(@as(u32, 0), fails);
}

test "AsmJit x64 assembler tests (800..1200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += check(&.{ 0x66, 0xF7, 0xD9 }, .@"neg", .{ gp.r16(.rcx) }, .{  }, "66F7D9 neg(cx)");
    fails += check(&.{ 0xF7, 0xD9 }, .@"neg", .{ gp.r32(.rcx) }, .{  }, "F7D9 neg(ecx)");
    fails += check(&.{ 0x48, 0xF7, 0xD9 }, .@"neg", .{ gp.r64(.rcx) }, .{  }, "48F7D9 neg(rcx)");
    fails += check(&.{ 0xF6, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"neg", .{ gp.byte(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "F69C1180000000 neg(byte_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x66, 0xF7, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"neg", .{ gp.word(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "66F79C1180000000 neg(word_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0xF7, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"neg", .{ gp.dword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "F79C1180000000 neg(dword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x48, 0xF7, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"neg", .{ gp.qword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "48F79C1180000000 neg(qword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x90 }, .@"nop", .{  }, .{  }, "90 nop()");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0xC1 }, .@"nop", .{ gp.r16(.rcx) }, .{  }, "660F1FC1 nop(cx)");
    fails += check(&.{ 0x0F, 0x1F, 0xC1 }, .@"nop", .{ gp.r32(.rcx) }, .{  }, "0F1FC1 nop(ecx)");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0xC1 }, .@"nop", .{ gp.r64(.rcx) }, .{  }, "480F1FC1 nop(rcx)");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0x84, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.word(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "660F1F841180000000 nop(word_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x0F, 0x1F, 0x84, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.dword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "0F1F841180000000 nop(dword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0x84, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.qword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "480F1F841180000000 nop(qword_ptr(rcx, rdx, 0, 128))");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0xD1 }, .@"nop", .{ gp.r16(.rcx), gp.r16(.rdx) }, .{  }, "660F1FD1 nop(cx, dx)");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.mem(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r16(.rbx) }, .{  }, "660F1F9C1180000000 nop(ptr(rcx, rdx, 0, 128), bx)");
    fails += check(&.{ 0x66, 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.word(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r16(.rbx) }, .{  }, "660F1F9C1180000000 nop(word_ptr(rcx, rdx, 0, 128), bx)");
    fails += check(&.{ 0x0F, 0x1F, 0xD1 }, .@"nop", .{ gp.r32(.rcx), gp.r32(.rdx) }, .{  }, "0F1FD1 nop(ecx, edx)");
    fails += check(&.{ 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.mem(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r32(.rbx) }, .{  }, "0F1F9C1180000000 nop(ptr(rcx, rdx, 0, 128), ebx)");
    fails += check(&.{ 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.dword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r32(.rbx) }, .{  }, "0F1F9C1180000000 nop(dword_ptr(rcx, rdx, 0, 128), ebx)");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0xD1 }, .@"nop", .{ gp.r64(.rcx), gp.r64(.rdx) }, .{  }, "480F1FD1 nop(rcx, rdx)");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.mem(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r64(.rbx) }, .{  }, "480F1F9C1180000000 nop(ptr(rcx, rdx, 0, 128), rbx)");
    fails += check(&.{ 0x48, 0x0F, 0x1F, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"nop", .{ gp.qword(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }), gp.r64(.rbx) }, .{  }, "480F1F9C1180000000 nop(qword_ptr(rcx, rdx, 0, 128), rbx)");
    fails += check(&.{ 0xF6, 0xD1 }, .@"not", .{ gp.r8(.rcx) }, .{  }, "F6D1 not_(cl)");
    fails += check(&.{ 0xF6, 0xD5 }, .@"not", .{ gp.r8hi(.rcx) }, .{  }, "F6D5 not_(ch)");
    fails += check(&.{ 0x66, 0xF7, 0xD1 }, .@"not", .{ gp.r16(.rcx) }, .{  }, "66F7D1 not_(cx)");
    fails += check(&.{ 0xF7, 0xD1 }, .@"not", .{ gp.r32(.rcx) }, .{  }, "F7D1 not_(ecx)");
    fails += check(&.{ 0x48, 0xF7, 0xD1 }, .@"not", .{ gp.r64(.rcx) }, .{  }, "48F7D1 not_(rcx)");
