test "AsmJit x64 assembler tests (1600..2000)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0xC4, 0xE2, 0x59, 0xE0, 0x9C, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"cmpoxadd", .{ vec.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128, .size = 4, .bcst = 0 }, gp.r32(.rbx), gp.r32(.rsp) }, .{  }, "C4E259E09C1180000000 cmpoxadd(dword_ptr(rcx, rdx, 0, 128), ebx, esp)");
