    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0xF2, 0x0F, 0x2A, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"cvtsi2sd", .{ vec.xmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 4, .bcst = 0 } }, .{  }, "F20F2A8C1A80000000 cvtsi2sd(xmm1, dword_ptr(rdx, rbx, 0, 128))");
