test "AsmJit x64 assembler tests (2400..2800)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x66, 0x0F, 0x75, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"pcmpeqw", .{ vec.xmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "660F758C1A80000000 pcmpeqw(xmm1, ptr(rdx, rbx, 0, 128))");
