test "AsmJit x64 assembler tests (3600..4000)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0xC4, 0xE2, 0x7D, 0x1E, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"vpabsd", .{ vec.ymm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "C4E27D1E8C1A80000000 vpabsd(ymm1, ptr(rdx, rbx, 0, 128))");
    fails += checkV(&.{ 0xC4, 0xE2, 0x7D, 0x1E, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"vpabsd", .{ vec.ymm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 32, .bcst = 0 } }, .{  }, "C4E27D1E8C1A80000000 vpabsd(ymm1, ymmword_ptr(rdx, rbx, 0, 128))");
