test "AsmJit x64 assembler tests (4800..5200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0xC4, 0xE2, 0x6D, 0x9A, 0xCB }, .@"vfmsub132ps", .{ vec.ymm(1), vec.ymm(2), vec.ymm(3) }, .{  }, "C4E26D9ACB vfmsub132ps(ymm1, ymm2, ymm3)");
