test "AsmJit x64 assembler tests (7200..7600)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xF2, 0x7E, 0x08, 0x13, 0x5C, 0x11, 0x10 }, .@"vpmovusdw", .{ vec.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 }, vec.xmm(3) }, .{  }, "62F27E08135C1110 vpmovusdw(ptr(rcx, rdx, 0, 128), xmm3)");
    fails += checkV(&.{ 0x62, 0xF2, 0x7E, 0x08, 0x13, 0x5C, 0x11, 0x10 }, .@"vpmovusdw", .{ vec.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128, .size = 8, .bcst = 0 }, vec.xmm(3) }, .{  }, "62F27E08135C1110 vpmovusdw(qword_ptr(rcx, rdx, 0, 128), xmm3)");
