test "AsmJit x64 assembler tests (10800..11200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0x93, 0xFD, 0xCA, 0x01, 0xDB, 0xAB }, .@"vpermpd", .{ vec.zmm(3), vec.zmm(27), 171 }, .{ .k = 2, .z = true }, "6293FDCA01DBAB vpermpd(zmm3, zmm27, 171)");
