test "AsmJit x64 assembler tests (12000..12400)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0x63, 0xDD, 0x58, 0x03, 0x21, 0x7B }, .@"valignq", .{ vec.zmm(28), vec.zmm(4), vec.Mem{ .base = .rcx, .scale = .x1, .disp = 0, .size = 8, .bcst = 8 }, 123 }, .{  }, "6263DD5803217B valignq(zmm28, zmm4, qword_ptr(rcx)._1to8(), 123)");
    fails += checkV(&.{ 0x62, 0x63, 0xDD, 0x48, 0x03, 0x62, 0x7F, 0x7B }, .@"valignq", .{ vec.zmm(28), vec.zmm(4), vec.Mem{ .base = .rdx, .scale = .x1, .disp = 8128, .size = 64, .bcst = 0 }, 123 }, .{  }, "6263DD4803627F7B valignq(zmm28, zmm4, zmmword_ptr(rdx, 8128), 123)");
    fails += checkV(&.{ 0x62, 0x63, 0xDD, 0x48, 0x03, 0xA2, 0x00, 0x20, 0x00, 0x00, 0x7B }, .@"valignq", .{ vec.zmm(28), vec.zmm(4), vec.Mem{ .base = .rdx, .scale = .x1, .disp = 8192, .size = 64, .bcst = 0 }, 123 }, .{  }, "6263DD4803A2002000007B valignq(zmm28, zmm4, zmmword_ptr(rdx, 8192), 123)");
    fails += checkV(&.{ 0x62, 0x63, 0xDD, 0x48, 0x03, 0x62, 0x80, 0x7B }, .@"valignq", .{ vec.zmm(28), vec.zmm(4), vec.Mem{ .base = .rdx, .scale = .x1, .disp = -8192, .size = 64, .bcst = 0 }, 123 }, .{  }, "6263DD480362807B valignq(zmm28, zmm4, zmmword_ptr(rdx, -8192), 123)");
