test "AsmJit x64 assembler tests (12800..13200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xB1, 0x7F, 0x18, 0x78, 0xC5 }, .@"vcvttsd2usi", .{ gp.r32(.rax), vec.xmm(21) }, .{ .sae = true }, "62B17F1878C5 vcvttsd2usi(eax, xmm21)");
    fails += checkV(&.{ 0x62, 0xF1, 0x7F, 0x08, 0x78, 0x01 }, .@"vcvttsd2usi", .{ gp.r32(.rax), vec.Mem{ .base = .rcx, .scale = .x1, .disp = 0, .size = 8, .bcst = 0 } }, .{  }, "62F17F087801 vcvttsd2usi(eax, qword_ptr(rcx))");
