test "AsmJit x64 assembler tests (16400..16800)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xF1, 0xC5, 0x40, 0x15, 0x31 }, .@"vunpckhpd", .{ vec.zmm(6), vec.zmm(23), vec.Mem{ .base = .rcx, .scale = .x1, .disp = 0, .size = 64, .bcst = 0 } }, .{  }, "62F1C5401531 vunpckhpd(zmm6, zmm23, zmmword_ptr(rcx))");
