    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0x63, 0xC5, 0x08, 0x0B, 0x92, 0xF8, 0xFB, 0xFF, 0xFF, 0x7B }, .@"vrndscalesd", .{ vec.xmm(26), vec.xmm(7), vec.Mem{ .base = .rdx, .scale = .x1, .disp = -1032, .size = 8, .bcst = 0 }, 123 }, .{  }, "6263C5080B92F8FBFFFF7B vrndscalesd(xmm26, xmm7, qword_ptr(rdx, -1032), 123)");
